    end
    Note over T1: ロックを取得 & 再開
    Note over T3: ロックを取得 & 再開




図 6.3: notifyAll() の図解





notifyAll() では、待機中のスレッドがすべて起こされます。ただし、ロックを持てるのは一度に1つだけなので、実際に再開するのは1つずつです。


重要なポイント

wait(), notify(), notifyAll() は、そのオブジェクトのロックを持っている状態でしか呼べません。（つまり、 synchronized ブロック／メソッドの中でしか呼べない）
wait() を呼んだスレッドがロックを手放すことによって、その間に他のスレッドが synchronized の中に入れるようになります。
notify() で起こされたスレッドは、ロックをもう一度取得できてから、wait() の次の行から処理を再開します。



サンプル：上限と下限のあるカウンタ
以下は、2つのスレッドが、変数 n をそれぞれ1000回ずつインクリメント（n++）またはデクリメント（n--）するプログラムです。
ただし、次のようにして、常に n の値が \([0, 10]\) の範囲に保たれるようにします。

n が10のときに、さらに増やそうとしたら、wait() で待つ
n が0のときに、さらに減らそうとしたら、wait() で待つ
増減に成功したら notify() を呼び、待っている相手のスレッドを起こす



WaitNotifyTest.java

public class WaitNotifyTest {
    int n = 0;

    synchronized void inc() {
        while (n == 10) {  // 上限に達している間は待つ（if ではなく while）
            System.out.println("nが10なので、加算を待機");
            try {
                wait();    // ロックを解放して待機
            } catch (InterruptedException e) {
                return;
            }
        }
        n++;
        System.out.println("Inc:" + n);
        notify();          // 減算を待っているスレッドを起こす
    }

    synchronized void dec() {
        while (n == 0) {   // 下限に達している間は待つ
            System.out.println("nが0なので、減算を待機");
            try {
                wait();
            } catch (InterruptedException e) {
                return;
            }
        }
        n--;
        System.out.println("Dec:" + n);
        notify();          // 加算を待っているスレッドを起こす
    }

    public static void main(String[] args) {
        WaitNotifyTest wt = new WaitNotifyTest();
        new IncThread(wt).start();
        new DecThread(wt).start();
    }
}

class IncThread extends Thread {
    WaitNotifyTest wt;

    public IncThread(WaitNotifyTest wt) {
        this.wt = wt;
    }

    public void run() {
        for (int i = 0; i &lt; 1000; i++) {
            wt.inc();
        }
    }
}

class DecThread extends Thread {
    WaitNotifyTest wt;

    public DecThread(WaitNotifyTest wt) {
        this.wt = wt;
    }

    public void run() {
        for (int i = 0; i &lt; 1000; i++) {
            wt.dec();
        }
    }
}







重要wait() は必ず if ではなく while ループの中で呼ぶ



wait() から戻ったときに、待っていた条件が満たされているとは限りません。理由は2つあります。

起こされてからロックを再取得するまでの間に、別のスレッドが先に値を変えている可能性がある。
Javaの仕様上、通知がなくても wait() から戻ることがある（見せかけの起床, spurious wakeup）。

while で囲んでおけば、戻った後にもう一度条件を確かめ、満たされていなければ再び待機させることができます。

7.2 サンプル：ナイフとフォーク
デッドロックという現象を理解するために、次のような状況を考えてください。

8人（Aさん, Bさん, …, Hさん）がいる
しかし、ナイフとフォークは1本ずつしかない
食事をするには、ナイフとフォークの両方を持っている必要がある
食事が終わったら、ナイフとフォークを返却する
8人は、10回ずつ食事をしなければならない

何が起こるか：

Aさんがフォークを、Bさんがナイフを取ったとします
Aさんはナイフの返却を、Bさんはフォークの返却を待ち続けます
どちらも自分の道具を手放しません
誰も食事ができなくなり、プログラムは終わらなくなります

上記の例をプログラムとして表現すると、以下のようになります。


DeadLockTest.java

public class DeadLockTest {
    // fork と knife には、それを持っている人のID番号（1〜8）が入る
    // ただし、誰もそれを持っていなければ 0 が入る
    int fork = 0;   // フォークを持っている人のID
    int knife = 0;  // ナイフを持っている人のID

    // ID番号を名前に変換する（1 → A, 2 → B, ..., 8 → H）
    static char name(int n) {
        return (char) ('A' + n - 1);
    }

    synchronized void getFork(int n) {
        if (fork != 0) {
            return;  // 誰かが持っているので取れない
        }
        fork = n;
        System.out.println(name(n) + " get Fork");
    }

    synchronized void getKnife(int n) {
        if (knife != 0) {
            return;
        }
        knife = n;
        System.out.println(name(n) + " get Knife");
    }

    synchronized void reset(int n) {  // 自分が持っている道具を返す
        if (fork == n) fork = 0;
        if (knife == n) knife = 0;
    }

    synchronized boolean canEat(int n) {  // 両方持っていれば食事できる
        return (fork == n) && (knife == n);
    }

    public static void main(String[] args) {
        DeadLockTest dlt = new DeadLockTest();
        for (int i = 1; i &lt; 9; i++) {
            new HumanThread(dlt, i).start();
        }
    }
}

class HumanThread extends Thread {
    DeadLockTest dlt;
    int id;

    public HumanThread(DeadLockTest dlt, int id) {
        this.dlt = dlt;
        this.id = id;
    }

    public void run() {
        for (int i = 0; i &lt; 10; i++) {
            while (!dlt.canEat(id)) {  // 両方そろうまで取りに行き続ける
                dlt.getFork(id);
                dlt.getKnife(id);
            }
            System.out.println(DeadLockTest.name(id) + " ate a meal.");
            dlt.reset(id);
        }
    }
}

各メソッドは synchronized なので、チャプター 4 の競合状態は起こりません。それでもデッドロックは起こります。つまり、排他制御が正しくても、資源の取り方（アルゴリズム）に問題があればデッドロックは起こるのです。






警告デッドロックの怖さ



実行のタイミングによっては、問題なく最後まで動くこともあります。そのため、テストで見つからずに残りやすく、原因の特定が難しい不具合になります。プログラムを設計する段階で、デッドロックが起こりえないかを確かめることが重要です。

8.3 サンプル：配列の要素を分担して増やす
要素数が100万である配列を考えます。
以下は、各要素を、1万回インクリメントするプログラムです。
コマンドライン引数でスレッド数を指定し、配列をスレッド数で等分して、各スレッドに担当させます。


ParaSample.java

public class ParaSample {
    static final int SIZE = 1000000;
    int[] array = new int[SIZE];

    public static void main(String[] args) throws InterruptedException {
        int num = Integer.parseInt(args[0]);  // スレッド数
        ParaSample ps = new ParaSample();
        ParaSampleThread[] threads = new ParaSampleThread[num];

        long startTime = System.currentTimeMillis();  // 計測開始

        // 配列を num 個に分け、各スレッドに担当範囲 [start, end) を割り当てる
        for (int i = 0; i &lt; num; i++) {
            int start = SIZE / num * i;
            int end = (i == num - 1) ? SIZE : SIZE / num * (i + 1);  // 最後のスレッドは端数も担当
            threads[i] = new ParaSampleThread(start, end, ps);
            threads[i].start();
        }

        // すべてのスレッドの終了を待つ
        for (int i = 0; i &lt; num; i++) {
            threads[i].join();
        }

        long endTime = System.currentTimeMillis();    // 計測終了
        System.out.println("処理時間: " + (endTime - startTime) + " ミリ秒");
    }
}

class ParaSampleThread extends Thread {
    int start;
    int end;
    ParaSample ps;

    public ParaSampleThread(int start, int end, ParaSample ps) {
        this.start = start;
        this.end = end;
        this.ps = ps;
    }

    public void run() {
        for (int i = 0; i &lt; 10000; i++) {
            for (int j = start; j &lt; end; j++) {
                ps.array[j]++;  // 担当範囲の要素だけを増やす
            }
        }
    }
}

各スレッドは配列の別々の範囲だけを書き換えるため、同じ要素を複数のスレッドが触ることはありません。そのため、チャプター 4 の排他制御は不要です。






警告



担当範囲の終わりは、最後のスレッドだけ SIZE にしています。たとえば3スレッドの場合、1000000 ÷ 3 の余り（1要素）が、どのスレッドにも割り当てられずに残るのを防ぐためです。

課題1：整理番号の発行
銀行や役所の窓口では、来た人に整理番号を配ります。 5つの窓口（スレッド）が、1台の番号発行機（Ticket オブジェクト）を共有して、整理番号を発行するプログラムを作成してください。
仕様

番号は1から始まる連番とする。
窓口は5つあり、各窓口が10000枚ずつ、合計50000枚の番号を発行する。
同じ番号を2回以上発行してはならない（重複なし）。
発行されない番号があってはならない（欠番なし）。つまり、1〜50000の番号が1回ずつ発行されなければならない。



Ticket.java

public class Ticket {
    static final int WINDOWS = 5;          // 窓口の数
    static final int PER_WINDOW = 10000;   // 1つの窓口が発行する枚数
    int next = 1;  // 次に発行する番号

    int issue() {
        // ここを記述：next の値を返し、next を1増やす
    }

    public static void main(String[] args) throws InterruptedException {
        Ticket ticket = new Ticket();
        Window[] windows = new Window[WINDOWS];
        for (int i = 0; i &lt; WINDOWS; i++) {
            windows[i] = new Window(ticket);
            windows[i].start();
        }
        for (int i = 0; i &lt; WINDOWS; i++) {
            windows[i].join();  // すべての窓口の発行が終わるまで待つ
        }
        check(windows);
    }

    /** 発行された番号に、重複と欠番がないかを調べる（変更しないこと） */
    static void check(Window[] windows) {
        int total = WINDOWS * PER_WINDOW;    // 発行した枚数
        int[] times = new int[total + 1];    // times[k] は、番号 k が発行された回数
        int outOfRange = 0;                  // 1〜total の範囲外の番号の数
        for (Window w : windows) {
            for (int number : w.issued) {
                if (1 &lt;= number && number &lt;= total) {
                    times[number]++;
                } else {
                    outOfRange++;
                }
            }
        }
        int duplicated = 0;  // 2回以上発行された番号の数
        int missing = 0;     // 1回も発行されなかった番号の数
        for (int k = 1; k &lt;= total; k++) {
            if (times[k] &gt;= 2) duplicated++;
            if (times[k] == 0) missing++;
        }
        System.out.println("発行枚数: " + total + "  重複した番号: " + duplicated
                + "  欠番: " + missing + "  範囲外: " + outOfRange);
        System.out.println((duplicated == 0 && missing == 0 && outOfRange == 0) ? "OK" : "NG");
    }
}

class Window extends Thread {
    Ticket ticket;
    int[] issued = new int[Ticket.PER_WINDOW];  // この窓口が発行した番号の記録

    public Window(Ticket ticket) {
        this.ticket = ticket;
    }

    public void run() {
        for (int i = 0; i &lt; Ticket.PER_WINDOW; i++) {
            issued[i] = ticket.issue();
        }
    }
}

各窓口は、発行した番号を自分専用の配列 issued に記録します。すべての窓口が終わった後、check() が全窓口の記録を集めて、重複と欠番の数を表示します。
